package org.mybatis.generator.codegen.mybatis3.vo;

import org.junit.jupiter.api.Test;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Comparator;
import java.util.UUID;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

class OfflineJakartaTemplateGeneratorTest {
    private static final String SOURCE = """
            /* The content below is generated by vgosoft's code factory. */
            package example;
            import javax.annotation.Resource;
            import javax.validation.constraints.AssertTrue;
            import javax.crypto.Cipher;
            import javax.sql.DataSource;
            import javax.annotation.Nullable;
            import javax.annotation.processing.Processor;
            public class Business {
                @Resource(name = "businessBean") private Object bean;
                @AssertTrue(message = "unchanged") private boolean valid;
                public String business() { return "javax.annotation.Resource"; }
            }
            """;

    @Test
    void shouldRegenerateOnlyExplicitApprovedAnnotationTypes() {
        String generated = OfflineJakartaTemplateGenerator.generate(SOURCE);
        assertThat(generated).isEqualTo(SOURCE
                .replace("import javax.annotation.Resource;", "import jakarta.annotation.Resource;")
                .replace("import javax.validation.constraints.AssertTrue;", "import jakarta.validation.constraints.AssertTrue;"));
    }

    @Test
    void shouldRejectUnprotectedOrUnrelatedSource() {
        assertThatThrownBy(() -> OfflineJakartaTemplateGenerator.generate(
                SOURCE.replace("The content below is generated by vgosoft's code factory.", "")))
                .isInstanceOf(IllegalArgumentException.class).hasMessageContaining("marker");
        assertThatThrownBy(() -> OfflineJakartaTemplateGenerator.generate(
                SOURCE.replace("import javax.annotation.Resource;", "").replace("import javax.validation.constraints.AssertTrue;", "")))
                .isInstanceOf(IllegalArgumentException.class).hasMessageContaining("No approved");
    }

    @Test
    void shouldKeepValidationAndInjectionAttributesAndBusinessCode() {
        assertThat(OfflineJakartaTemplateGenerator.generate(SOURCE))
                .contains("@Resource(name = \"businessBean\")")
                .contains("@AssertTrue(message = \"unchanged\")")
                .contains("return \"javax.annotation.Resource\";")
                .contains("import javax.annotation.Nullable;")
                .contains("import javax.annotation.processing.Processor;");
    }

    @Test
    void shouldApplyManifestOnlyWhenOriginalSnapshotAndOutputAreUnchanged() throws Exception {
        Path run = Path.of("target", "offline-jakarta-test-" + UUID.randomUUID());
        Path sourceRoot = run.resolve("business");
        Path source = sourceRoot.resolve(Path.of("module", "src", "main", "java", "Business.java"));
        Path snapshots = run.resolve("snapshots");
        Path staging = run.resolve("staging");
        Path manifest = run.resolve("manifest.properties");
        try {
            Files.createDirectories(source.getParent());
            Files.writeString(source, SOURCE);
            OfflineJakartaTemplateGenerator.main(new String[]{"stage", sourceRoot.toString(),
                    snapshots.toString(), staging.toString(), manifest.toString()});
            assertThat(Files.readString(source)).isEqualTo(SOURCE);
            Files.writeString(source, SOURCE + "// concurrent user extension\n");
            assertThatThrownBy(() -> OfflineJakartaTemplateGenerator.main(
                    new String[]{"apply", manifest.toString()}))
                    .isInstanceOf(IllegalStateException.class).hasMessageContaining("Changed source");
            assertThat(Files.readString(source)).contains("concurrent user extension");
            Files.writeString(source, SOURCE);
            OfflineJakartaTemplateGenerator.main(new String[]{"apply", manifest.toString()});
            assertThat(Files.readString(source)).isEqualTo(OfflineJakartaTemplateGenerator.generate(SOURCE));
            assertThat(Files.readString(snapshots.resolve(sourceRoot.relativize(source)))).isEqualTo(SOURCE);
        } finally {
            if (Files.exists(run)) {
                try (var paths = Files.walk(run)) {
                    for (Path path : paths.sorted(Comparator.reverseOrder()).toList()) {
                        Files.delete(path);
                    }
                }
            }
        }
    }
}
